class Solution {
public:
    int tilt = 0;
    int weigh(TreeNode* node) {
        if (!node) return 0;
        int l = weigh(node->left);
        int r = weigh(node->right);
        tilt += abs(l - r);
        return node->val + l + r;
    }
    int findTilt(TreeNode* root) {
        weigh(root);
        return tilt;
    }
};
